ation:isolate;display:grid;grid-template-columns:104px minmax(0,1fr) 76px;padding:7px 12px 11px;column-gap:0}\n.room{position:absolute;inset:0;overflow:hidden;z-index:-2;background:radial-gradient(ellipse at 50% 41%,#ffcc8866,transparent 62%),linear-gradient(90deg,#a34724,#da9460 48%,#b3582c)}\n.room:after{content:\"\";position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,#6c2d1722,transparent 42%,#d29c3d0a);box-shadow:inset 0 15px 35px #69321825}\n.window{position:absolute;left:24%;top:57px;width:55%;height:365px;border:9px solid #e8bc7c;border-radius:100px 100px 3px 3px;background:linear-gradient(#9bc7cd,#c4d6cf 70%,#e4d3ac);box-shadow:0 0 0 5px #b77a42,0 0 0 9px #d8a66b,0 0 32px #ffe0a966;overflow:hidden}\n.window:before{content:\"\";position:absolute;left:46%;top:0;width:7px;height:100%;background:#ecd09a;box-shadow:2px 0 3px #926b4630}\n.window:after{content:\"\";position:absolute;left:0;top:60%;width:100%;height:7px;background:#e8c28b;box-shadow:0 2px 2px #9e734533}\n.cloud{position:absolute;width:83px;height:26px;border-radius:50%;background:#eee5c58c;top:128px;left:40px;transform:rotate(-9deg);box-shadow:64px 93px 0 5px #f3e9cf66,-30px 149px 0 -3px #eee6cc88}\n.curtain{position:absolute;top:72px;height:333px;width:58px;background:linear-gradient(90deg,#c99456,#f3d5a1 30%,#dfb579 59%,#ae713e 90%);box-shadow:4px 5px 7px #6e3c2922}\n.curtain.left{left:18%;border-radius:35% 13% 46% 12%;transform:rotate(-4deg)}\n.curtain.right{right:17%;border-radius:10% 35% 9% 45%;transform:rotate(4deg);background:linear-gradient(90deg,#b98049,#edc68c 35%,#f4d5a1 68%,#c18b50)}\n.curtain:after{content:\"\";position:absolute;left:2px;right:2px;bottom:52px;height:13px;background:linear-gradient(#e1bd84,#cba069);border-radius:60%;transform:rotate(-8deg)}\n.valance{position:absolute;top:33px;left:15%;width:70%;height:56px;border-radius:50% 50% 45% 45%;border-top:12px solid #a86a36;background:linear-gradient(#ac713f,#d09c65);box-shadow:0 5px 4px #80512630}\n.room-floor{position:absolute;left:-10%;right:-10%;bottom:-5px;height:245px;background:repeating-linear-gradient(0deg,transparent 0 45px,#99522120 46px 48px),linear-gradient(90deg,#bb7745,#e7b66e 45%,#b46735);transform:perspective(400px) rotateX(15deg);transform-origin:bottom}\n.rug{position:absolute;bottom:-35px;left:13%;width:88%;height:233px;border-radius:50%;background:radial-gradient(ellipse at 48% 35%,#efd06c 0 19%,#91a56b 21% 53%,#7d8b5b 70%);transform:rotate(-9deg);box-shadow:0 3px 5px #5c5c3433}\n.desk{position:absolute;right:-24px;top:361px;width:133px;height:17px;border-radius:5px;background:linear-gradient(#e7ad65,#a25120);box-shadow:0 5px 0 #a1572a}\n.desk:after{content:\"\";position:absolute;right:26px;top:16px;width:13px;height:120px;background:linear-gradient(90deg,#9d4a21,#cb7838)}\n.shelf{position:absolute;right:-9px;top:239px;width:59px;height:7px;border-radius:4px;background:#a95b29;box-shadow:0 3px 4px #79422440}\n.shelf:before{content:\"\";position:absolute;left:9px;bottom:7px;width:15px;height:25px;border-radius:5px 5px 0 0;background:#d9984e;box-shadow:19px -8px 0 2px #bb6434}\n.chair{position:absolute;left:-14px;top:328px;width:89px;height:137px;border:7px solid #d9a064;border-radius:12px 8px 3px 3px;background:linear-gradient(#7e915e 0 66%,#926135 67%)}\n.chair:after{content:\"\";position:absolute;left:12px;top:48px;width:13px;height:13px;border-radius:50%;background:#eac579;box-shadow:36px 0 #eac579}\n.left-rail,.right-rail{display:flex;flex-direction:column;justify-content:space-between;z-index:4;min-width:0}\n.left-rail{grid-column:1;align-items:flex-start}\n.promotions{display:flex;flex-direction:column;gap:10px;padding-top:4px}\n.promo{display:flex;flex-direction:column;align-items:center;justify-content:flex-end;position:relative;width:50px;height:49px;padding:0;background:transparent;color:white}\n.promo-art{height:37px;width:43px;display:grid;place-items:center}\n.promo-label{font-size:11px;font-weight:750;line-height:17px;height:17p