ansparent;color:#fff9ed;position:relative}\n.tool-disc{position:relative;display:grid;place-items:center;width:40px;height:40px;border-radius:50%;background:#dc783fc4;box-shadow:inset 0 1px 0 #ffbd7b12}\n.side-tool:nth-child(2) .tool-disc{background:#dc8652}\n.side-tool:nth-child(3) .tool-disc{background:#cd9276}\n.side-tool:nth-child(4) .tool-disc{background:#e39870}\n.side-tool:nth-child(5) .tool-disc{background:#d77c3d}\n.side-tool .label{font-size:13px;line-height:18px;text-shadow:0 1px 3px #793c2140}\n.tool-disc svg{width:24px;height:24px}\n.badge{position:absolute;right:-2px;top:-1px;min-width:17px;height:17px;line-height:17px;border-radius:10px;background:#f23d39;text-align:center;font-size:11px;color:#fff}\n.quick-actions{display:flex;flex-direction:column;align-items:flex-end;gap:8px;width:68px}\n.quick{position:relative;width:67px;height:55px;border:1px solid #ec9c65;border-radius:14px;background:#6d665596;padding:4px 2px 2px;display:flex;flex-direction:column;align-items:center;justify-content:flex-end;color:white;box-shadow:inset 0 1px 0 #fff2d15c}\n.quick-art{height:34px;width:44px;margin-top:-15px;display:grid;place-items:center;filter:drop-shadow(0 3px 2px #68422b44)}\n.quick-art svg{width:44px;height:38px}\n.quick-label{font-size:11px;line-height:17px}\n.task-badge{position:absolute;top:-13px;right:0;background:#f23c32;border:1px solid #ffd1a6;border-radius:4px;font-size:10px;line-height:14px;padding:0 2px}\n.gacha{height:60px;background:#795e4d9c}\n.gacha .quick-art{height:43px;width:37px;margin-top:-15px}\n.gacha img{width:35px;height:43px;object-fit:contain;display:block}\n.collection{height:54px;background:#67584cba}\n.collection .quick-art{height:20px;align-self:flex-end;margin:-12px 9px 0 0;width:30px}\n.collection .quick-art svg{width:30px;height:30px}\n.collection-progress{height:12px;width:51px;border:1px solid #583b25;border-radius:10px;background:linear-gradient(90deg,#b35d28 56%,#684329 56%);font-size:10px;line-height:10px}\n.pet-art{posi