sub:#686868;\n  --border-light:#e5e5e9;\n  --nav-background:#eae6ef;\n  --nav-ink:#827f89;\n}\n*{box-sizing:border-box}\nbody{margin:0;background:#303037;font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",\"PingFang SC\",\"Microsoft YaHei\",sans-serif}\nbutton,input,textarea{font:inherit}\nbutton{cursor:pointer;-webkit-tap-highlight-color:transparent;white-space:nowrap}\nbutton:focus-visible,textarea:focus-visible{outline:2px solid var(--primary);outline-offset:3px}\nsvg{display:block}\n.page{\n  width:100%;max-width:375px;min-height:833px;margin:0 auto;\n  display:flex;flex-direction:column;color:var(--text-main);overflow:hidden;\n  background:radial-gradient(ellipse 300px 260px at 100% 0%,#ffdbcf 0%,transparent 100%),\n             radial-gradient(ellipse 330px 260px at 0% 0%,#fff6dc 0%,transparent 100%),\n             linear-gradient(180deg,#faf3ec 0%,#f5f3f3 25%,var(--bg-page) 43%);\n}\n.status{\n  height:32px;min-height:32px;flex:none;padding:0 24px;\n  display:flex;align-items:center;justify-content:space-between;color:#494943;\n}\n.time{font-size:14px;font-weight:600;line-height:18px}\n.signals{width:72px;height:18px;flex:none}\n.content{flex:1;padding:0 12px}\n.profile{display:flex;align-items:center;gap:12px;margin:71px 10px 23px;height:61px}\n.avatar{\n  width:60px;height:60px;aspect-ratio:1;flex:none;overflow:hidden;\n  border-radius:50%;background:#4c89b5;\n}\n.avatar svg{width:100%;height:100%}\n.profile-copy{display:flex;flex-direction:column;gap:5px}\n.profile-name{font-size:23px;line-height:27px;font-weight:700;margin:0;letter-spacing:-.4px}\n.profile-caption{font-size:12px;line-height:17px;color:var(--text-sub);margin:0}\n.preferences{display:grid;grid-template-columns:1fr 1fr;gap:12px}\n.preference-card{\n  height:51px;display:flex;align-items:center;justify-content:space-between;\n  gap:7px;padding:0 12px;border-radius:18px;background:var(--bg-card);\n}\n.preference-label{font-size:16px;font-weight:600;line-height:22px;white-space:nowrap}\n.services{margin-top:23px}\n.section-heading{margin:0 10px 11px;font-size:16px;font-weight:600;line-height:20px}\n.service-card{border-radius:18px;background:var(--bg-card);overflow:hidden}\n.service-row{\n  display:flex;align-items:center;gap:13px;width:100%;height:50px;\n  padding:0 12px;border:0;background:transparent;text-align:left;color:var(--text-main);\n}\n.service-symbol{width:30px;height:30px;border-radius:9px;display:grid;place-items:center;flex:none;color:#fff}\n.service-symbol.settings{background:#18bfc5}\n.service-symbol.help{background:#0b86f6}\n.service-symbol svg{width:22px;height:22px}\n.service-label{font-size:16px;font-weight:500;line-height:22px;flex:1}\n.chevron{color:#cdcdcd;flex:none}\n.service-divider{height:1px;border:0;background:#dcdce0;margin:0 12px 0 55px}\n.bottom-nav{\n  height:68px;min-height:68px;flex:none;display:flex;align-items:stretch;\n  justify-content:space-around;padding:4px 0 8px;border-top:1px solid #dedee5;\n  background:var(--nav-background);\n}\n.nav-item{\n  display:flex;flex:1 1 0;flex-direction:column;align-items:center;justify-content:center;\n  gap:4px;min-width:0;padding:0;border:0;background:transparent;color:var(--nav-ink);\n  font-size:11px;line-height:14px;font-weight:500;\n}\n.nav-item svg{width:22px;height:22px;flex:none}\n.nav-item[aria-current=\"page\"]{color:var(--primary)}\n.wf-modal{\n  display:none;position:fixed;inset:0;z-index:20;padding:24px;\n  background:rgba(32,29,34,.42);align-items:center;justify-content:center;\n}\n.wf-modal.wf-show{display:flex}\n.modal-card{\n  position:relative;width:100%;max-width:327px;padding:24px 20px 20px;\n  border:1px solid #ffffffb3;border-radius:18px;background:#fff;\n  box-shadow:0 18px 60px #22222926;\n}\n.modal-title{margin:0 30px 16px 0;font-size:19px;line-height:26px;font-weight:600}\n.modal-copy{margin:0 0 18px;font-size:13px;line-height:1.8;color:var(--text-sub)}\n.close{\n  position:absolute;top:17px;right:15px;display:grid;place-items:center;\n  width:28px;height:28px;padding:0;border:0;background:transparent;color:#888;\n}\n.feedback-input{\n  display:block;width:100%;min-height:112px;resize:vertical;padding:12px;\n  border:1px solid var(--border-light);border-radius:11px;background:#f8f8fa;\n  color:var(--text-main);font-size:13px;line-height:1.6;\n}\n.feedback-note{margin:9px 0 18px;color:#929298;font-size:11px;line-height:17px}\n.confirm{width:100%;height:42px;padding:0 16px;border:0;border-radius:11px;background:var(--primary);color:white;font-size:14px;font-weight:600}\n@media(max-width:350px){\n  .preference-card{padding:0 9px;gap:4px}\n  .preference-label{font-size:14px}\n  .preferences{gap:8px}\n}\n</style>\n<meta name=\"wf-renderer\" content=\"ai-static-v1\"><style data-wf-prototype-style=\"true\">[hidden]{display:none!important}\n[data-wf-asset-missing]{display:flex;align-items:center;justify-content:center;min-height:80px;border-radius:14px;background:var(--primary-subtle,#eeeaf9);color:var(--text-sub,#64748b)}\n.wf-modal{position:fixed;inset:0;display:flex;align-items:center;justify-content:center;background:rgba(0,0,0,.4);z-index:1000}\n.wf-modal:not(.wf-show){opacity:0;visibility:hidden;pointer-events:none}\n.wf-modal.wf-show{display:flex!important;opacity:1;visibility:visible;pointer-events:auto}\n#wf-prototype-feedback{position:fixed;bottom:84px;left:50%;transform:translateX(-50%);max-width:90%;padding:10px 16px;border-radius:12px;background:#172033;color:white;font:13px/1.5 system-ui;z-index:100001}\n</style><style data-wf-artwork-style=\"true\">[data-wf-artwork-resolved=true]{position:relative!important;overflow:hidden}\n[data-wf-artwork-resolved=true]>[data-wf-artwork-fallback]{display:none!important}\n[data-wf-artwork-resolved=true]>img[data-wf-artwork-image]{position:absolute!important;inset:0!important;width:100%!important;height:100%!important;object-fit:var(--wf-artwork-fit,cover)!important;object-position:var(--wf-artwork-position,center top)!important;transform:none!important;display:block}