color:transparent;white-space:nowrap}\nbutton:focus-visible{outline:2px solid #ffe6bb;outline-offset:3px}\nbutton:active{filter:brightness(1.1)}\nsvg{display:block}\n.app{width:100%;max-width:375px;min-height:833px;margin:0 auto;background:linear-gradient(180deg,#211f30 0%,#34354b 29%,#707d98 100%);color:var(--text-main);overflow:hidden}\n.status{height:32px;padding:0 24px;display:flex;align-items:center;justify-content:space-between;color:#c6c4d0}\n.time{font-size:14px;line-height:18px;font-weight:600}\n.signals{display:flex;align-items:center;width:72px;height:18px;gap:1px}\n.signals svg{flex:1;min-width:0;height:18px}\n.header{height:56px;padding:8px 19px 6px;display:flex;align-items:center;justify-content:space-between}\n.header-tool{width:39px;height:39px;flex:none;border:0;border-radius:50%;background:#46435d;color:#fff;display:grid;place-items:center;padding:7px;position:relative}\n.header-tool svg{width:24px;height:24px}\n.dot{position:absolute;right:1px;top:2px;width:9px;height:9px;background:#ff3937;border-radius:50%}\n.tabs{display:flex;align-items:center;width:144px;height:39px;padding:4px;border-radius:24px;background:#3e3b55}\n.tab{flex:1;min-width:0;border:0;background:transparent;color:#b4afc4;font-size:16px;line-height:31px;height:31px;padding:0 8px;border-radius:20px;font-weight:500}\n.tab.active{background:#565169;color:#f5f1fa}\n.content{height:677px;padding:12px 12px 14px}\n.notice{display:flex;align-items:center;width:100%;height:47px;padding:0 14px 0 20px;border:0;border-radius:26px;background:#dcdbe6;color:#15141a;text-align:left;gap:9px}\n.notice-art{width:20px;height:24px;flex:none;color:#bc8c48}\n.notice-text{font-size:14px;line-height:20px;letter-spacing:-.25px;flex:1}\n.notice-text strong{color:var(--primary);font-weight:600}\n.notice-arrow{width:18px;height:18px;flex:none}\n.collection-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:23px 9px;margin-top:24px}\n.character-card{height:178px;min-width:0;border:1px solid #77a9dc;border-radius:21px;overflow:hidden;background:linear-gradient(180deg,#252253 0%,#484b6c 82%,#62677f 100%);box-shadow:inset 0 0 0 .3px #99c2ed40}\n.character-card.epic{border-color:#b492f4;background:linear-gradient(180deg,#29183e 0%,#4a405f 82%,#666079 100%)}\n.character-card.light{border-color:#4aa8b5;background:linear-gradient(180deg,#1c3039 0%,#455263 82%,#697689 100%)}\n.character-stage{height:147px;position:relative;isolation:isolate;overflow:hidden;background:radial-gradient(ellipse at 50% 66%,#ffffff0a,transparent 65%)}\n.artwork{position:absolute;left:3px;right:3px;bottom:2px;height:133px;aspect-ratio:104/133;display:flex;align-items:center;justify-content:center;filter:drop-shadow(0 4px 3px #11112035)}\n.artwork>svg{width:100%;height:100%;overflow:visible}\n.artwork[data-wf-artwork-resolved=\"true\"]{overflow:hidden;filter:drop-shadow(0 4px 3px #11112035)}\n.artwork[data-wf-artwork-resolved=\"true\"]>[data-wf-artwork-fallback]{display:none}\n.artwork>img[data-wf-artwork-image]{width:100%;height:100%;object-fit:contain;object-position:center bottom;display:block}\n.rarity{position:absolute;z-index:3;left:12px;top:11px;transform:rotate(-7deg);color:#bfc2ff;font-size:13px;line-height:19px;font-weight:900;font-style:italic;letter-spacing:-1px;text-shadow:-1px -1px 0 #f3efff,1px 1px 0 #22225b,2px 2px 0 #272452,0 0 4px #ddd4ff}\n.rarity.epic-label{color:#ffa5dc;text-shadow:-1px -1px 0 #fff2f8,1px 1px 0 #5b244b,2px 2px 0 #4b244b,0 0 4px #f2c6f4}\n.rarity.light-label{color:#b8e6ff;text-shadow:-1px -1px 0 #f0ffff,1px 1px 0 #263b71,2px 2px 0 #263856,0 0 4px #b7f8ff}\n.rarity:after{content:\"✦\";position:absolute;right:-4px;top:-6px;font-size:8px;color:#fff}\n.new-label{position:absolute;top:8px;right:8px;z-index:4;background:#ff3b34;color:#fff;font-size:11px;line-height:16px;padding:0 4px;border-radius:10px;font-weight:400}\n.card-dot{position:absolute;right:8px;top:8px;width:9px;height:9px;border-radius:50%;background:#ff3937;z-index:4}\n.seal{position:absolute;right:7px;bottom:7px;width:40px;height:40px;display:flex;flex-direction:column;align-items:center;justify-content:center;color:#10191b;font-size:10px;font-weight:900;font-style:italic;line-height:13px;z-index:4;isolation:isolate;transform:rotate(4deg);filter:drop-shadow(0 1px 1px #1b1b3333)}\n.seal:before{content:\"\";position:absolute;inset:0;z-index:-1;clip-path:polygon(50% 0,61% 9%,77% 6%,82% 22%,98% 29%,93% 45%,100% 59%,86% 70%,83% 88%,65% 89%,52% 100%,40% 91%,23% 94%,18% 78%,2% 71%,7% 53%,0 40%,14% 28%,17% 11%,36% 12%);background:linear-gradient(135deg,#8be8e5,#f5ffdf 51%,#eab6f4 82%);border:1px solid #fff}\n.seal:after{content:\"\";position:absolute;inset:5px;z-index:-1;border:1px solid #a9bdbd80;border-radius:7px;transform:rotate(9deg)}\n.seal small{font-size:7px;letter-spacing:2px;line-height:10px}\n.seal.trial{background:none;width:40px;height:40px;font-size:10px;line-height:12px;transform:rotate(-7deg)}\n.seal.trial:before{background:linear-gradient(120deg,#d7b985,#fff3c4,#d9bc91)}\n.progress{position:absolute;left:50%;bottom:6px;transform:translateX(-50%);height:17px;width:57px;padding:0 6px;border:1px solid #f7c095;border-radius:12px;color:white;background:#ff6d12;display:flex;align-items:center;justify-content:center;gap:4px;font-size:11px;line-height:15px;z-index:5}\n.progress svg{width:12px;height:13px;flex:none}\n.progress .dot{top:-6px;right:-5px;width:9px;height:9px}\n.progress.partial{border-color:#a6a5a6;background:linear-gradient(90deg,#9c6543 33%,#37404c 33%)}\n.card-name{height:30px;margin:0;display:flex;justify-content:center;align-items:center;background:#ffffff07;font-size:13px;line-height:18px;font-weight:400;color:#fff;position:relative}\n.footer-rarity{position:absolute;left:12px;top:-4px;color:#ffb1e1;font-size:12px;line-height:16px;font-weight:900;font-style:italic;transform:rotate(-5deg);text-shadow:-1px -1px #fff1fc,1px 1px #592448,2px 2px #372740}\n.bottom-nav{height:68px;display:flex;align-items:stretch;justify-content:space-ar