f}\nbutton{font:inherit;cursor:pointer;border:0;white-space:nowrap;-webkit-tap-highlight-color:transparent}\nbutton:focus-visible{outline:2px solid #fff4a7;outline-offset:4px}\nsvg,img{display:block}\n.app{width:100%;max-width:375px;min-height:833px;height:833px;margin:0 auto;position:relative;overflow:hidden;background:var(--bg-page);color:var(--text-main)}\n.home{height:833px;display:flex;flex-direction:column;background:linear-gradient(#ed711d,#fbb05c 36%,#e9bb77 78%,#bb8045)}\n.status{height:32px;min-height:32px;padding:0 24px;display:flex;align-items:center;justify-content:space-between;color:#fff;font-size:14px;font-weight:600;line-height:18px;background:transparent}\n.header{height:58px;flex:none;padding:12px 25px 10px;display:flex;align-items:center;justify-content:space-between;color:#fff4de}\n.header h1{font-size:20px;line-height:28px;margin:0;font-weight:700}\n.wallets{display:flex;gap:10px}\n.wallet{height:26px;border:1px solid #ffdab4;border-radius:20px;display:flex;gap:8px;align-items:center;padding:0 10px;font-size:14px;font-weight:600}\n.room{position:relative;flex:1;min-height:0;isolation:isolate;overflow:hidden}\n.room-art{position:absolute;inset:0;z-index:-2;background:radial-gradient(ellipse at 54% 48%,#fff2b2 0,transparent 56%),linear-gradient(90deg,#d98a44,#f2c176 44%,#edab62 80%,#ce8140)}\n.room-art:before{content:\"\";position:absolute;left:21%;right:15%;top:6%;height:52%;border:14px solid #edc68b;border-bottom-width:22px;border-radius:130px 130px 8px 8px;background:linear-gradient(90deg,transparent 47%,#f2d7a4 47% 53%,transparent 53%),linear-gradient(transparent 49%,#f2d7a4 49% 53%,transparent 53%),linear-gradient(135deg,#8dd8e1,#c9e9d9);box-shadow:0 0 0 7px #d1904c,0 0 0 15px #edab60}\n.room-art:after{content:\"\";position:absolute;left:-15%;right:-20%;bottom:0;height:31%;border-radius:50% 50% 0 0;background:radial-gradient(ellipse at 40% 35%,#f6cf62 0 17%,transparent 18%),radial-gradient(ellipse at 75% 70%,#f4cc5d 0 18%,transparent 19%),#9db76d;border:15px solid #c5c67b;box-shadow:0 -13px 0 #e3ad6d}\n.shelf{position:absolute;right:-8px;top:32%;height:230px;width:65px;border:9px solid #c96d32;border-top-width:13px;background:repeating-linear-gradient(0deg,#edbd71 0 65px,#c96d32 66px 76px);transform:rotate(-2deg);box-shadow:0 4px 12px #b85b2466}\n.plant{position:absolute;left:-18px;top:41%;width:55px;height:80px;background:radial-gradient(ellipse at 30% 20%,#7fa450 0 24%,transparent 25%),radial-gradient(ellipse at 70% 37%,#9bb865 0 25%,transparent 26%);border-bottom:27px solid #d98549;border-radius:40%}\n.background-top{display:flex;align-items:flex-start;justify-content:space-between;padding:15px 14px 0}\n.promos{display:flex;flex-direction:column;gap:15px;padding-top:3px}\n.promo{background:transparent;padding:0;width:47px;display:flex;flex-direction:column;align-items:center;color:white}\n.promo img{width:43px;height:37px;object-fit:contain}\n.promo span{font-size:10px;line-height:14px;font-weight:700;border-radius:8px;padding:0 3px;background:#ffb28b;margin-top:-1px}\n.promo.gift span{background:#ae70dc;border-radius:2px}\n.promo.pet span{background:#ec9a13}\n.bubbles{display:flex;gap:8px;align-items:flex-start;padding-top:13px;margin-left:8px}\n.bubble-item{display:flex;align-items:center;flex-direction:column;gap:5px;color:#fff2d6;font-size:12px;line-height:16px;text-align:center}\n.bubble-item:first-child{margin-top:27px}\n.bubble-item:last-child{margin-top:22px}\n.bubble{width:49px;height:49px;border-radius:50%;background:radial-gradient(circle at 37% 30%,#ffffff5c,transparent 40%);border:1px solid #fff8dba6;box-shadow:inset 2px 2px 5px #fff9d877,inset -2px -2px 4px #ffffe52e,0 0 0 2px #ffffff24;display:grid;place-items:center}\n.bubble svg{width:28px;height:31px}\n.shortcuts{display:flex;flex-direction:column;gap:15px;align-items:center;width:43px;margin-left:6px}\n.shortcut{background:transparent;color:#fff3df;padding:0;display:flex;flex-direction:column;align-items:center;gap:5px;font-size:12px}\n.shortcut-icon{width:38px;height:38px;display:grid;place-items:center;border-radius:50%;background:#f58b39;position:relative}\n.shortcut-icon svg{width:23px;height:23px}\n.shortcut small{position:absolute;right:-3px;top:0;border-radius:20px;background:#ef5147;padding:0 5px;font-size:11px}\n.pet-art{position:absolute;left:100px;top:241px;width:196px;height:290px;object-fit:contain;filter:drop-shadow(0 8px 5px #9c702b44)}\n.home-lower{position:absolute;left:13px;right:13px;bottom:12px;display:flex;justify-content:space-between;align-items:flex-end}\n.home-settings{width:104px;display:flex;flex-direction:column;gap:8px}\n.setting{display:flex;align-items:center;gap:6px;width:75px;height:29px;background:#de9c4d;border-radius:19px;padding:3px 7px;color:#fff9e9;font-size:13px}\n.stats{border-radius:14px;padding:9px 8px;background:#99996cb3;color:#fff7de;font-size:11px;line-height:18px;margin-top:5px}\n.stats h2{display:flex;align-items:center;justify-content:space-between;font-size:15px;line-height:22px;margin:0 0 3px}\n.stats p{margin:0}\n.switch-pet{margin-top:10px;width:100%;height:29px;border:1px solid #efc353;border-radius:18px;background:linear-gradient(#ffe586,#ffb32f);font-weight:700;font-size:13px;color:#965924}\n.lower-links{display:flex;flex-direction:column;gap:25px;margin-bottom:0}\n.lower-link{width:67px;min-height:42px;border:1px solid #eeb06b;border-radius:13px;background:#d18d4f;color:#fff7e3;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:3px;font-size:11px}\n.lower-link svg{margin-top:-13px}\n.bottom-nav{height:68px;min-height:68px;display:flex;align-items:stretch;justify-content:space-around;padding:4px 0 8px;border-top:1px solid #dedee5;background:#eae6ef}\n.nav-item{flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:4px;padding:0;background:transparent;color:#827f89;font-size:11px;line-height:14px;font-weight:500}\n.nav-item[aria-current=page]{color:#ff7020}\n.shade{position:absolute;inset:0;background:rgba(34,18,9,.66);z-index:5}\n.reward-dialog{position:absolute;inset:0;z-index:6;display:flex;flex-direction:column;align-items:center;padding-top:216px}\n.dialog-intro{height:96px;width:313px;display:flex;align-items:flex-end;position:relative;flex:none}\n.messenger{height:103px;width:99px;object-fit:contain;object-position:center bottom;position:relative;z-index:2;margin-left:0}\n.speech{position:absolute;left:112px;right:6px;bottom:17px;height:36px;display:flex;align-items:center;justify-content:center;background:linear-gradient(100deg,#f5f7ed,#f7e4d7);border-radius:14px;color:#1d1b18;font-size:14px;white-space:nowrap}\n.speech:before{content:\"\";position:absolute;left:-7px;top:11px;width:15px;height:15px;background:#f5f5e9;transform:rotate(45deg);border-radius:3px}\n.reward-card{width:313px;height:232px;flex:none;display:flex;flex-direction:column;align-items:center;padding:30px 26px 24px;border-radius:32px;background:radial-gradient(ellipse at 4% 2%,#fff0b4c9,transparent 64%),radial-gradient(ellipse at 96% 3%,#ffb48f9c,transparent 65%),linear-gradient(115deg,#f7e8d1,#f0e9df 65%,#f5dcd3);position:relative;overflow:hidden}\n.reward-card:before{content:\"\";position:absolute;inset:0;pointer-events:none;opacity:.2;background-image:radial-gradient(circle,#eeb16c 0 5px,transparent 5.5px),radial-gradient(circle,#f2af72 0 3px,transparent 3.5px);background-size:42px 35px,35px 44px;background-position:0 0,22px 16px;mask-image:linear-gradient(#000,transparent 95%)}\n.reward-art{width:88px;height:67px;flex:none;position:relative;filter:drop-shadow(0 3px 2px #6d8d9270)}\n.reward-title{position:relative;display:flex;align-items:center;gap:6px;margin:17px 0 0;font-size:15px;line-height:23px;font-weight:500}\n.reward-title strong{font-size:15px;color:#ff6518;font-weight:500}\n.reward-note{position:relative;margin:0;font-size:11px;line-height:18px;color:#70685e;white-space:nowrap}\n.claim{position:relative;width:219px;max-width:100%;height:39px;min-