atus-signals{display:block;width:72px;height:18px}\n.home-header{height:64px;flex:none;padding:16px 25px 12px;display:flex;align-items:center;justify-content:space-between;gap:10px;color:white}\n.home-title{margin:0;font-size:20px;font-weight:700;letter-spacing:1px}\n.balances{display:flex;gap:10px}\n.balance{height:26px;border:1px solid #ffdab899;border-radius:20px;display:flex;align-items:center;gap:9px;padding:0 9px;font-size:14px;font-weight:600}\n.balance svg{display:block}\n.home-scene{height:96px;flex:none;display:flex;align-items:center;justify-content:space-between;padding:0 15px;background:radial-gradient(ellipse at 52% 95%,#ffe6b070,transparent 70%)}\n.scene-promo{width:48px;height:67px;display:flex;flex-direction:column;align-items:center;justify-content:center}\n.scene-promo img{width:43px;height:45px;object-fit:contain}\n.scene-promo span{margin-top:-3px;background:#e97d4f;border-radius:12px;padding:1px 5px;color:#fff0d2;font-size:10px;font-weight:700;white-space:nowrap}\n.scene-bubbles{display:flex;align-items:center;gap:8px;transform:translateY(12px)}\n.bubble{width:49px;height:49px;display:grid;place-items:center;border:1px solid #fff7d67a;border-radius:50%;box-shadow:inset 2px 3px 6px #fff6cd88,inset -2px -3px 5px #b7835c55;background:#ffeac617}\n.bubble:nth-child(2){transform:translateY(-25px)}\n.scene-membership{display:flex;flex-direction:column;align-items:center;gap:5px;color:#fff4dc;font-size:13px}\n.crown{width:38px;height:38px;border-radius:50%;background:#ea6d21;display:grid;place-items:center}\n.bag{min-height:641px;border-radius:35px 35px 0 0;background:#fff9f3;padding:8px 12px 20px;display:flex;flex-direction:column}\n.sheet-handle{height:21px;display:flex;justify-content:center;align-items:flex-start;color:#d7d1cb}\n.bag-title{font-size:20px;line-height:28px;font-weight:700;margin:10px 13px 15px}\n.bag-tabs{display:flex;gap:17px;margin:0 13px 13px;height:32px}\n.bag-tab{position:relative;font-size:16px;line-height:25px;color:#65615e;font-weight:500}\n.bag-tab.active{color:var(--primary);font-weight:600}\n.bag-tab.active:after{content:\"\";position:absolute;bottom:0;left:0;right:0;height:2px;border-radius:3px;background:var(--primary)}\n.inventory{background:#fff;border-radius:20px;padding:17px 13px 20px;min-height:316px}\n.inventory-heading{display:flex;align-items:center;justify-content:space-between;gap:6px;margin-bottom:13px}\n.inventory-heading h3{margin:0;font-size:14px;font-weight:600;white-space:nowrap}\n.stat{display:flex;align-items:center;gap:7px;font-size:13px;white-space:nowrap}\n.stat svg{width:14px;height:14px}\n.stat-meter{height:13px;width:65px;background:linear-gradient(90deg,#ff7b15 53%,#d9d7d6 53%);border-radius:10px;color:white;text-align:center;font-size:10px;line-height:13px}\n.items{display:grid;grid-template-columns:repeat(3,75px);gap:8px;margin-bottom:16px}\n.inventory-item{display:flex;flex-direction:column;gap:8px;align-items:center}\n.inventory-item>span{font-size:13px;line-height:18px;white-space:nowrap}\n.item-picture{width:75px;height:75px;position:relative;border-radius:20px;border:2px solid;display:flex;align-items:center;justify-content:center;overflow:hidden}\n.item-picture svg{width:58px;height:51px}\n.item-yellow{background:linear-gradient(#fff68d,#ffd94c);border-color:#e5b200}\n.item-blue{background:linear-gradient(#7af1ed,#4ad0ed);border-color:#00bad9}\n.item-purple{background:linear-gradient(#f2a8ef,#bd77e9);border-color:#a56ae9}\n.item-pink{background:linear-gradient(#ffc08e,#ff668e);border-color:#ff638b}\n.item-count{position:absolute;right:0;top:0;width:21px;height:17px;border-radius:0 0 0 8px;background:inherit;color:white;text-align:center;font-size:12px;line-height:16px}\n.item-value{position:absolute;bottom:2px;right:7px;color:white;font-weight:700;font-size:15px;line-height:18px}\n.inventory-heading.second{margin-top:1px}\n.inventory-continuation{margin-top:12px;min-height:165px;border-radius:20px;background:#fff}\n.purchase-layer{position:absolute;