en}\n.home-name{font-size:21px;font-weight:700;letter-spacing:1px}\n.balances{display:flex;gap:10px}\n.balance{border:1px solid #ffe7bd99;border-radius:20px;display:flex;align-items:center;justify-content:center;gap:9px;height:26px;padding:0 10px;font-size:14px;font-weight:600}\n.home-stage{position:relative;height:160px;isolation:isolate}\n.scenery{position:absolute;inset:8px 32px -35px;border-radius:55% 55% 0 0;background:radial-gradient(ellipse at 50% 90%,#a4d9cf 0 31%,#f6c788 32% 42%,#df9c58 43% 47%,#b87137 48%);filter:blur(1px)}\n.scenery:before,.scenery:after{content:\"\";position:absolute;top:-5px;width:75px;height:31px;border-radius:45%;background:#6c8133;box-shadow:0 17px 0 -8px #95612e}\n.scenery:before{left:10px;transform:rotate(-12deg)}.scenery:after{right:8px;transform:rotate(12deg)}\n.home-promo{position:absolute;left:14px;top:12px;width:49px;text-align:center}\n.home-promo img{display:block;width:43px;height:39px;object-fit:contain;margin:auto}\n.home-promo span{display:block;background:#ffa169;border-radius:10px;font-size:10px;font-weight:700}\n.month{position:absolute;right:14px;top:14px;display:flex;flex-direction:column;align-items:center;gap:4px;font-size:13px}\n.crown-disc{width:39px;height:39px;background:#ff8139;border-radius:50%;display:grid;place-items:center}\n.reward-orbs{position:absolute;top:29px;left:111px;display:flex;gap:9px;align-items:center}\n.orb{height:50px;width:50px;border:2px solid #fff9;border-radius:50%;display:grid;place-items:center;background:radial-gradient(circle at 30% 20%,#ffffff55,transparent 45%);box-shadow:inset 0 0 0 3px #fff2,0 3px 5px #805c3a33}\n.orb:nth-child(2){transform:translateY(-25px)}\n.home-download{position:absolute;top:81px;left:170px;font-size:13px;line-height:20px;text-align:center}\n.sheet{height:642px;position:relative;display:flex;flex-direction:column;background:radial-gradient(ellipse at 0 3%,#ecdbd4,transparent 55%),radial-gradient(ellipse at 55% 54%,#e7e6d9,transparent 65%),linear-gradient(13