h d=\"M0 171c20-27 37-20 42-2l-3 69H0ZM334 174c18-19 32-13 41 2v62h-39Z\" fill=\"#e5a063\" />\n        <path d=\"M336 215h29v23h-29Z\" fill=\"#ee9b52\" />\n        <path d=\"m331 215 20-19 20 19\" fill=\"#da7041\" />\n      </svg>\n\n      <div class=\"offers\" data-wf-id=\"home-offers\" data-wf-role=\"card\" data-wf-uid=\"wf-p2540-home-offers\">\n        <button class=\"offer\" data-wf-id=\"btn-new-low-price\" data-wf-role=\"button\" data-nav=\"横滑活动特价弹窗\" aria-label=\"上新低价\" data-wf-uid=\"wf-p2540-btn-new-low-price\" type=\"button\">\n          <img src=\"/api/assets/artwork/182/25b45646c75df20669ac0fdc5f70af904759a8c0b0a46270b8ec268b4343b304.png\" data-wf-id=\"new-low-price-cat\" data-wf-role=\"image\" alt=\"粉色坐垫招财猫\" data-wf-uid=\"wf-p2540-new-low-price-cat\">\n          <span data-wf-id=\"text-new-low-price\" data-wf-role=\"text\" data-wf-uid=\"wf-p2540-text-new-low-price\">上新低价</span>\n        </button>\n        <button class=\"offer gift\" data-wf-id=\"btn-first-order-offer\" data-wf-role=\"button\" data-nav=\"单张活动弹窗\" aria-label=\"首单特价\" data-wf-uid=\"wf-p2540-btn-first-order-offer\" type=\"button\">\n          <svg class=\"gift-art\" data-wf-id=\"first-order-gift\" data-wf-role=\"image\" width=\"38\" height=\"36\" viewBox=\"0 0 38 36\" fill=\"none\" data-wf-uid=\"wf-p2540-first-order-gift\">\n            <defs><linearGradient id=\"gift-box\" x1=\"4\" y1=\"9\" x2=\"33\" y2=\"35\" gradientUnits=\"userSpaceOnUse\"><stop stop-color=\"#ceb3ff\" /><stop offset=\"1\" stop-color=\"#9876dc\" /></linearGradient></defs>\n            <path d=\"m4 12 29-2 2 22-28 3Z\" fill=\"url(#gift-box)\" stroke=\"#e3b9fc\" />\n            <path d=\"m2 10 30-3 4 5-31 4Z\" fill=\"#cfb3f5\" stroke=\"#f2caff\" />\n            <path d=\"m16 11 6-1 2 23-6 1Z\" fill=\"#d99bdd\" />\n            <path d=\"M19 10C6 8 7-3 14 2c4 3 5 8 5 8Zm0 0C30 4 29-3 23 1c-5 4-4 9-4 9Z\" fill=\"#b88dec\" stroke=\"#efd2ff\" stroke-width=\"1.5\" />\n            <path d=\"m9 21 2 3m18-6-2 3M12 30l2-2\" stroke=\"#f3c6a8\" stroke-width=\"1.4\" />\n          </svg>\n          <span data-wf-id=\"text-first-order-offer\" data-wf-role=\"text\" data-wf-uid=\"wf-p2540-text-first-order-offer\">首单特价</span>\n        </button>\n        <button class=\"offer pet\" data-wf-id=\"btn-new-pet\" data-wf-role=\"button\" data-nav=\"更换耀宝页\" aria-label=\"上新耀宝\" data-wf-uid=\"wf-p2540-btn-new-pet\" type=\"button\">\n          <img src=\"/api/assets/artwork/182/8fea276c7ca64d4511be8a1ea062e2cba5ff202b0c2f34c2232a522bf8f4d510.png\" data-wf-id=\"new-pet-nailong\" data-wf-role=\"image\" alt=\"戴耳机围巾的奶龙\" data-wf-uid=\"wf-p2540-new-pet-nailong\">\n          <span data-wf-id=\"text-new-pet\" data-wf-role=\"text\" data-wf-uid=\"wf-p2540-text-new-pet\">上新耀宝</span>\n        </button>\n      </div>\n\n      <div class=\"rewards\" data-wf-id=\"floating-rewards\" data-wf-role=\"card\" data-wf-uid=\"wf-p2540-floating-rewards\">\n        <div class=\"reward first\" data-wf-id=\"gift-reward\" data-wf-role=\"card\" data-wf-uid=\"wf-p2540-gift-reward\">\n          <div class=\"bubble\" data-wf-id=\"gift-reward-bubble\" data-wf-role=\"card\" data-wf-uid=\"wf-p2540-gift-reward-bubble\">\n            <svg data-wf-id=\"gift-reward-diamond\" data-wf-role=\"icon\" width=\"27\" height=\"30\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" data-wf-uid=\"wf-p2540-gift-reward-diamond\"><path d=\"m7 1 11 1 5 10-5 11H7L1 13Z\" fill=\"#1661df\" stroke=\"none\" /><path d=\"m7 1 5 8 6-7Z\" fill=\"#a4eaff\" stroke=\"none\" /><path d=\"M1 13 12 9 7 1Z\" fill=\"#4dc5ff\" stroke=\"none\" /><path d=\"m12 9 11 3-5-10Z\" fill=\"#428aef\" stroke=\"none\" /><path d=\"M1 13 12 9l6 14H7Z\" fill=\"#164fc1\" stroke=\"none\" /><path d=\"m12 9 11 3-5 11Z\" fill=\"#119ff5\" stroke=\"none\" /></svg>\n          </div>\n          <span data-wf-id=\"text-gift-reward\" data-wf-role=\"text\" data-wf-uid=\"wf-p2540-text-gift-reward\">送个礼物</span>\n        </div>\n        <div class=\"reward second\" data-wf-id=\"download-diamond-reward\" data-wf-role=\"card\" data-wf-uid=\"wf-p2540-download-diamond-reward\">\n          <div class=\"bubble\" data-wf-id=\"download-diamond-bubble\" data-wf-role=\"card\" data-wf-uid=\"wf-p2540-download-diamond-bubble\">\n            <svg data-wf-id=\"download-diamond-icon\" data-wf-role=\"icon\" width=\"27\" height=\"30\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" data-wf-uid=\"wf-p2540-download-diamond-icon\"><path d=\"m7 1 11 1 5 10-5 11H7L1 13Z\" fill=\"#1661df\" stroke=\"none\" /><path d=\"m7 1 5 8 6-7Z\" fill=\"#a4eaff\" stroke=\"none\" /><path d=\"M1 13 12 9 7 1Z\" fill=\"#4dc5ff\" stroke=\"none\" /><path d=\"m12 9 11 3-5-10Z\" fill=\"#428aef\" stroke=\"none\" /><path d=\"M1 13 12 9l6 14H7Z\" fill=\"#164fc1\" stroke=\"none\" /><path d=\"m12 9 11 3-5 11Z\" fill=\"#119ff5\" stroke=\"none\" /></svg>\n          </div>\n          <span data-wf-id=\"text-download-diamond\" data-wf-role=\"text\" data-wf-uid=\"wf-p2540-text-download-diamond\">下载完成<br>领取奖励</span>\n        </div>\n        <div class=\"reward third\" data-wf-id=\"download-energy-reward\" data-wf-role=\"card\" data-wf-uid=\"wf-p2540-download-energy-reward\">\n          <div class=\"bubble\" data-wf-id=\"download-energy-bubble\" data-wf-role=\"card\" data-wf-uid=\"wf-p2540-download-energy-bubble\">\n            <svg data-wf-id=\"download-energy-icon\" data-wf-role=\"icon\" width=\"27\" height=\"30\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" data-wf-uid=\"wf-p2540-download-energy-icon\"><path d=\"M6 1h12l-4 7h7L11 24H7l3-11H1Z\" fill=\"#ffb93e\" stroke=\"none\" /><path d=\"m6 1 5 2-3 9H1Zm8 7h7L11 24l3-13Z\" fill=\"#ffec90\" stroke=\"none\" /></svg>\n          </div>\n          <span data-wf-id=\"text-download-energy\" data-wf-role=\"text\" data-wf-uid=\"wf-p2540-text-download-energy\">下载完成<br>领取奖励</span>\n        </div>\n      </div>\n\n      <div class=\"quick-links\" data-wf-id=\"home-quick-links\" data-wf-role=