ight:600;line-height:18px}\n.status-icons{display:flex;align-items:center;gap:5px}\n.topbar{height:54px;display:flex;align-items:center;gap:8px;padding:0 17px 0 25px}\nh1{font-size:20px;font-weight:600;line-height:28px;margin:0}\n.currency{height:26px;border:1px solid #83a9cf;border-radius:20px;display:flex;gap:5px;align-items:center;padding:0 8px 0 6px;font-size:14px;font-weight:400}\n.app-actions{margin-left:auto;display:flex;height:34px;border:1px solid #91b5d8;border-radius:22px;overflow:hidden}\n.app-action{width:45px;background:transparent;border:0;display:flex;align-items:center;justify-content:center;position:relative;padding:0}\n.app-action+.app-action:before{content:\"\";position:absolute;left:0;height:19px;width:1px;background:#86a8ca}\n.main-tabs{height:46px;display:flex;align-items:stretch;padding:0 10px 0 18px;gap:0}\n.main-tab{padding:0 9px;border:0;background:transparent;font-size:14px;color:#54616e;position:relative}\n.main-tab.active{background:#fff;color:#4e5095;font-size:19px;font-weight:700;border-radius:13px 13px 0 0;padding:0 17px}\n.main-tab.active:before,.main-tab.active:after{content:\"\";position:absolute;bottom:0;width:13px;height:13px;pointer-events:none}\n.main-tab.active:before{left:-13px;border-radius:0 0 13px 0;box-shadow:4px 4px 0 3px #fff}\n.main-tab.active:after{right:-13px;border-radius:0 0 0 13px;box-shadow:-4px 4px 0 3px #fff}\n.main-tab.draw{padding-left:14px;padding-right:0}\n.main-tab.event{padding-left:0;padding-right:10px}\n.main-tab.event:before{content:\"/\";padding-right:0}\n.main-tab.live{padding-left:13px}\n.main-tab.live:before{content:\"\";height:12px;width:1px;background:#9babbf;position:absolute;left:0;top:17px}\n.tools{height:58px;flex:none;display:flex;align-items:center;gap:9px;padding:5px 17px 9px}\n.vip{height:44px;flex:0 0 85px;position:relative;overflow:hidden;text-align:left;padding:4px 6px;border-radius:7px;border:1px solid #adb3c7;background:linear-gradient(125deg,#9da4bc,#67748d);color:#fff;box-shadow:0