parent}\\nbutton:focus-visible{outline:2px solid #8581ff;outline-offset:4px}\\nsvg{display:block;flex-shrink:0}\\n.page{position:relative;width:100%;max-width:375px;min-height:833px;height:833px;margin:0 auto;overflow:hidden;background:var(--bg-page)}\\n.collection{height:833px;display:flex;flex-direction:column;background:linear-gradient(120deg,#f4e8d0,#e9c494 77%,#efdab8)}\\n.status{height:32px;min-height:32px;display:flex;align-items:center;justify-content:space-between;padding:0 24px;color:#20212b}\\n.time{font-size:14px;font-weight:600;line-height:18px}\\n.signals{display:flex;align-items:center;gap:5px}\\n.header{height:54px;flex:none;display:flex;align-items:center;padding:0 16px 0 25px;gap:8px}\\n.header h1{margin:0 auto 0 0;font-size:20px;font-weight:600}\\n.balance{height:26px;border:1px solid #b4a68e;border-radius:20px;display:flex;align-items:center;gap:8px;padding:0 10px 0 7px;font-size:14px;line-height:20px}\\n.conversion{margin:16px 25px 14px;min-height:49px;display:flex;align-items:center;gap:12px;padding:0 15px;background:#fffaf0;border:0;border-radius:13px;text-align:left;font-size:14px}\\n.conversion .chevron{margin-left:auto;color:#bcb4a6}\\n.collection-scroll{flex:1;min-height:0;overflow:hidden}\\n.shelf{height:138px;display:flex;align-items:flex-end;gap:11px;padding:12px 16px 14px;position:relative;background:linear-gradient(180deg,#dfba86,#f0d4a9 87%,#f9e7c9 88%,#ead5b6 96%,#d8bd97 97%);border-bottom:10px solid #f2dfbe;box-shadow:inset 0 9px 15px #bb98632b}\\n.shelf:first-child{height:132px;padding-top:3px}\\n.series{flex:0 0 25px;width:25px;height:100px;align-self:flex-end;display:flex;justify-content:center;align-items:center;position:relative;background:linear-gradient(90deg,#223c6b,#45608a,#263e6a);border:2px solid #e3ce8b;clip-path:polygon(50% 0,100% 8%,100% 92%,50% 100%,0 92%,0 8%);box-shadow:inset 0 0 0 2px #9baec1;color:#f4f5ff}\\n.series span{writing-mode:vertical-rl;font-size:16px;font-weight:800;letter-spacing:3px;text-shadow:1px 1px #203354}\\n.series.green{background:linear-gradient(90deg,#286157,#49877b,#245c56)}\\n.characters{display:flex;align-items:flex-end;flex:1;min-width:0;height:112px;padding-left:2px}\\n.character{position:relative;flex:0 0 57px;width:57px;height:106px;padding:13px 4px 6px;border:1px solid #c3cfe3;border-radius:3px;background:linear-gradient(135deg,#3b5880,#a6c1d6 30%,#d3d3ee 70%,#718db9);box-shadow:0 2px 1px #fff9;transform:rotate(-3deg)}\\n.character+.character{margin-left:-19px}\\n.character:nth-child(2){transform:rotate(0deg)}\\n.character:nth-child(3){transform:rotate(-1deg)}\\n.character:nth-child(4){transform:rotate(1deg)}\\n.character:nth-child(5){transform:rotate(-3deg)}\\n.character:after{content:\\\"\\\";position:absolute;left:-3px;right:-3px;bottom:-5px;height:8px;border-radius:1px;background:linear-gradient(#f5f7ff,#d8e1ec);box-shadow:0 2px 2px #ad987244}\\n.character img{width:100%;height:100%;display:block;object-fit:cover;object-position:center 18%;border:1px solid #d9c278;border-radius:10px 3px 6px 4px;background:#6655a1}\\n.card-brand{position:absolute;top:1px;left:0;right:0;height:12px;text-align:center;font-family:serif;font-size:8px;font-weight:700;line-height:11px;color:#f4f7ff;background:linear-gradient(90deg,#3d527c,#657ea6,#3a4c74);white-space:nowrap;overflow:hidden}\\n.character.green-card{background:linear-gradient(130deg,#3f9784,#bfd8bc,#81a898)}\\n.green-card .card-brand{background:linear-gradient(90deg,#338b79,#65b5a2,#337f71)}\\n.notice-dot{position:absolute;left:-3px;top:-5px;width:10px;height:10px;border:1px solid white;border-radius:50%;background:#ee3e2e;z-index:2}\\n.rarity{position:absolute;bottom:1px;left:1px;z-index:1;font-size:12px;line-height:16px;font-weight:900;color:#e8e0ff;text-shadow:-1px -1px #4b329d,1px 1px #4b329d,-1px 1px #4b329d,1px -1px #4b329d;transform:rotate(-8deg)}\\n.reward{flex:0 0 64px;width:64px;height:112px;display:flex;flex-direction:column;align-items:center;justify-content:flex-end;position:relative}\\n.reward-card{width:55px;height:96px;background:linear-gradient(145deg,#f4f9fc,#d5e7ed);border:2px solid #f7faff;border-radius:2px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;transform:rotate(-2deg)}\\n.reward-value{font-size:11px;line-height:15px}\\n.reward-caption{position:relative;margin:-7px -7px 0;font-size:11px;line-height:12px;font-weight:900;text-align:center;color:#f1ecff;text-shadow:-1px -1px #4d3483,1px 1px #4d3483,-1px 1px #4d3483,1px -1px #4d3483;z-index:1;white-space:nowrap}\\n.reward-caption em{font-style:normal;color:#f5ed68}\\n.empty{background:linear-gradient(110deg,#e3eff16b,#e7f4f276);border-color:#d2e0db99;box-shadow:none}\\n.empty:before{content:\\\"\\\";display:block;height:100%;border-radius:18px 18px 5px 5px;background:#dbe9e36b}\\n.empty .card-brand{opacity:.25}\\n.bottom-nav{position:relative;height:75px;min-height:75px;display:flex;align-items:stretch;justify-content:space-around;padding:4px 0 8px;background:#fff;border-top:1px solid #dedee5}\\n.nav-item{position:relative;display:flex;flex:1;min-width:0;flex-direction:column;align-items:center;justify-content:center;gap:4px;background:transparent;border:0;padding:0;color:#686969;font-size:11px;font-weight:500;line-height:14px}\\n.nav-item svg{width:22px;height:22px}\\n.nav-item.active{color:white}\\n.nav-item.active .active-tile{position:absolute;top:0;left:50%;width:50px;height:50px;transform:translateX(-50%);border-radius:9px;background:linear-gradient(#879bfa,#88d4ff)}\\n.nav-item svg,.nav-item .nav-label{position:relative}\\n.nav-divider{position:absolute;left:41%;top:16px;width:1px;height:25px;background:#e5e5e5}\\n.home-indicator{position:absolute;bottom:6px;left:50%;transform:translateX(-50%);width:125px;height:4px;background:#858585;border-radius:4px}\\n.modal-layer{position:absolute;inset:0;z-index:10;display:flex;align-items:center;justify-content:center;padding:24px;background:rgba(0,0,0,.41)}\\n.dialog{width:326px;max-width:100%;min-heig