INSERT INTO `page` VALUES (2602,184,'家园','D:\\idea\\Project\\html版本\\html不是很好版\\designs\\5.0\\436.png',375,833,NULL,NULL,7,1,'2026-11-11 09:31:49','<!doctype html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<meta name=\"theme-color\" content=\"#030407\">\n<title>家园</title>\n<style>\n:root{\n  --bg-page:#030407;\n  --bg-card:#ecf0ff;\n  --primary:#4859ff;\n  --primary-subtle:#dce4ff;\n  --text-main:#fff;\n  --text-sub:#c4c5d1;\n  --border-light:#636478;\n  --wf-chrome-status-height:32px;\n  --wf-chrome-nav-height:75px;\n  --wf-chrome-nav-font:11px;\n  --wf-chrome-nav-bg:#fff;\n  --wf-chrome-nav-ink:#686969;\n  --wf-chrome-active:#fff;\n  --wf-chrome-border:#dedee5;\n  --wf-chrome-active-bg:linear-gradient(#879bfa,#88d4ff);\n  --wf-chrome-active-radius:9px;\n}\n*{box-sizing:border-box}\nbody{margin:0;background:#303033;color:var(--text-main);font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",\"PingFang SC\",\"Microsoft YaHei\",sans-serif;-webkit-font-smoothing:antialiased}\nbutton{font:inherit;color:inherit;cursor:pointer;border:0;padding:0;background:none;white-space:nowrap;-webkit-tap-highlight-color:transparent}\nbutton:focus-visible{outline:2px solid #b5c9ff;outline-offset:3px}\nsvg{display:block;flex-shrink:0}\n.page{width:100%;max-width:375px;height:833px;min-height:833px;overflow:hidden;margin:0 auto;display:flex;flex-direction:column;background:var(--bg-page)}\n.status{height:32px;min-height:32px;padding:0 24px;display:flex;align-items:center;justify-content:space-between;color:#fff;flex:none}\n.time{font-size:14px;line-height:18px;font-weight:600}\n.signals{display:flex;align-items:center;gap:4px;width:72px;height:18px}\n.signals svg{height:18px}\n.header{height:61px;flex:none;display:flex;align-items:flex-start;padding:7px 12px 0 17px;gap:9px}\n.header-main{display:flex;align-items:center;gap:15px;flex:1;height:35px;min-width:0}\n.back{width:24px;height:30px;displ