n input{margin:0;flex:none}\n.scene-bottom{position:absolute;left:15px;right:16px;bottom:7px;display:flex;align-items:flex-end;justify-content:space-between;pointer-events:none}\n.scene-bottom button{pointer-events:auto}\n.wallpapers{width:62px;height:62px;display:flex;flex-direction:column;align-items:center;justify-content:flex-end}\n.wallpaper-art{height:41px;width:46px;position:relative;display:flex;align-items:center;justify-content:center}\n.wallpaper-card{width:29px;height:39px;border:2px solid #fff;border-radius:4px;background:linear-gradient(135deg,#7ba5ff,#6b59d4);transform:rotate(-12deg);box-shadow:-5px 3px 0 -1px #b9cbff;display:grid;place-items:center}\n.wallpaper-card svg{width:23px;height:23px}\n.wallpapers-label{margin-top:-2px;font-size:11px;color:#466080;padding:2px 7px;border-radius:12px;border:1px solid #a7b5ff;background:#e2f0ff;position:relative;z-index:1}\n.explore{width:50px;height:51px;margin-bottom:27px;border-radius:50%;background:radial-gradient(circle at 45% 35%,#f9f8ff,#a2c8ff 49%,#2cc7ec 75%,#1a617b);border:1px solid #9a9ac4;box-shadow:0 0 8px #5ce0ff55;position:relative;display:flex;align-items:center;justify-content:center}\n.explore svg{width:43px;height:42px}\n.explore-label{position:absolute;bottom:7px;font-weight:800;color:white;font-size:10px;text-shadow:1px 1px #cb6c33,-1px -1px #cb6c33,1px -1px #cb6c33,-1px 1px #cb6c33}\n.action-area{height:88px;flex:none;padding:10px 16px 16px;display:grid;grid-template-columns:76px minmax(0,160px) 76px;gap:16px;align-items:end;background:linear-gradient(#070a0d,#000);z-index:3}\n.action-card{height:62px;border:1px solid #e6e0fc;border-radius:14px;background:linear-gradient(#c8d9ff,#f9f9ff 80%);color:#24252b;position:relative}\n.daily{display:flex;flex-direction:column;justify-content:center;align-items:center;gap:1px}\n.daily svg{width:37px;height:37px}\n.daily-title{font-size:12px;line-height:16px}\n.reward-badge{position:absolute;top:-11px;right:-15px;z-index:2;background:#f03d32;border:1p