INSERT INTO `page` VALUES (2648,184,'家园页','D:\\idea\\Project\\html版本\\html不是很好版\\designs\\5.0\\458.png',375,833,NULL,NULL,13,1,'2026-11-11 17:53:22','<!doctype html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<meta name=\"theme-color\" content=\"#030304\">\n<title>家园页</title>\n<style>\n:root{\n  --bg-page:#030305;\n  --bg-card:#f5f7ff;\n  --primary:#354afa;\n  --primary-subtle:#e6ebff;\n  --text-main:#ffffff;\n  --text-sub:#d3d2dd;\n  --border-light:#dfe1ef;\n  --wf-chrome-status-height:32px;\n  --wf-chrome-nav-height:75px;\n  --wf-chrome-nav-font:11px;\n  --wf-chrome-nav-bg:#fff;\n  --wf-chrome-nav-ink:#686969;\n  --wf-chrome-active:#fff;\n  --wf-chrome-border:#dedee5;\n  --wf-chrome-active-bg:linear-gradient(#879bfa,#88d4ff);\n  --wf-chrome-active-radius:9px;\n  --wf-chrome-viewport-height:833px;\n}\n*{box-sizing:border-box}\nbody{margin:0;background:#303033;font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",\"PingFang SC\",\"Microsoft YaHei\",sans-serif;-webkit-font-smoothing:antialiased;color:var(--text-main)}\nbutton{font:inherit;color:inherit;cursor:pointer;border:0;padding:0;white-space:nowrap;-webkit-tap-highlight-color:transparent}\nbutton:focus-visible{outline:2px solid #a5cfff;outline-offset:3px}\nbutton:active{filter:brightness(1.1)}\nsvg{display:block;flex-shrink:0}\n.page{width:100%;max-width:375px;min-height:833px;height:833px;overflow:hidden;margin:auto;display:flex;flex-direction:column;background:var(--bg-page);position:relative}\n.status{height:32px;min-height:32px;display:flex;align-items:center;justify-content:space-between;padding:0 24px;background:transparent;color:#fff;flex:none}\n.time{font-size:14px;line-height:18px;font-weight:600}\n.header{height:62px;flex:none;display:flex;align-items:flex-start;padding:9px 16px 0;gap:8px;z-index:3;background:#030304}\n.back{width:24px;height:30px;flex:none;display:flex;align-items:center;justify-content:center;background:none}\n.title{font-size:20px;font-weight:600;margin:3px 12px 0 18px;line-height:26px;white-space:nowrap}\n.resources{display:flex;gap:8px;flex:1;min-width:0;margin-top:4px}\n.resource{height:27px;border:1px solid #57575b;border-radius:18px;display:flex;align-items:center;justify-content:center;gap:7px;padding:0 8px;flex:1;min-width:0;font-size:14px;font-variant-numeric:tabular-nums}\n.energy{color:#ffd82c;filter:drop-shadow(0 1px 2px #7f4f00)}\n.diamond{color:#52b5ff}\n.monthly{width:37px;flex:none;display:flex;flex-direction:column;align-items:center;gap:1px;background:transparent;position:relative;margin-top:0}\n.monthly-label{font-size:11px;line-height:15px}\n.notify{width:15px;height:15px;border-radius:50%;background:#f34336;border:1.5px solid white;position:absolute;right:0;top:-5px;box-shadow:0 1px 3px #0004}\n.monthly-art{width:29px;height:30px;color:#c8cbd0;filter:drop-shadow(0 1px 2px #fff5)}\n.stage{flex:1;min-height:0;position:relative;isolation:isolate;background:#030305;overflow:hidden;display:flex;flex-direction:column;padding:7px 15px 0}\n.scene-art{position:absolute;top:61px;left:0;right:0;height:530px;max-height:calc(100% - 61px);z-index:-2;pointer-events:none;overflow:hidden}\n.scene-art img{width:100%;height:100%;max-width:100%;display:block;object-fit:contain;object-position:center bottom;transform:none}\n.ambient{position:absolute;inset:0;z-index:-3;overflow:hidden;pointer-events:none;background:linear-gradient(transparent 78%,#070b13)}\n.upper-stage{display:grid;grid-template-columns:53px minmax(0,1fr) 43px;gap:5px;align-items:start}\n.activity-rail{display:flex;flex-direction:column;gap:11px;padding-top:1px}\n.activity{width:50px;height:51px;position:relative;display:flex;flex-direction:column;align-items:center;justify-content:flex-start;background:transparent}\n.activity-disc{height:43px;width:43px;border:1.5px solid #fff6e2;border-radius:50%;display:flex;align-items:center;justify-content:center;background:radial-gradient(circle