 event.target.value.trim().toLocaleLowerCase();\\n    scope.querySelectorAll(\'[data-wf-search-text]\').forEach(function (item) {\\n      item.hidden = !(item.getAttribute(\'data-wf-search-text\') || item.textContent).toLocaleLowerCase().includes(query);\\n    });\\n  });\\n  document.addEventListener(\'keydown\', function (event) {\\n    if (event.key === \'Escape\' && !editing() && !hosted()) {\\n      document.querySelectorAll(\'.wf-modal.wf-show\').forEach(close);\\n    }\\n  });\\n})();\\n\\u003c/script>\\u003c/body>\\n\\u003c/html>\",\"2601\":\"\\u003c!doctype html>\\n\\u003chtml lang=\\\"zh-CN\\\">\\n\\u003chead>\\n\\u003cmeta charset=\\\"UTF-8\\\">\\n\\u003cmeta name=\\\"viewport\\\" content=\\\"width=device-width,initial-scale=1\\\">\\n\\u003ctitle>背包道具弹窗\\u003c/title>\\n\\u003cstyle>\\n:root{--bg-page:#f3f4f6;--bg-card:#fff;--primary:#ec9228;--primary-subtle:#fff1d5;--text-main:#08090a;--text-sub:#787b7d;--border-light:#eceef1;--wf-chrome-status-height:32px;--wf-chrome-nav-height:75px;--wf-chrome-nav-font:11px}\\n*{box-sizing:border-box}\\nbody{margin:0;background:#303033;font-family:-apple-system,BlinkMacSystemFont,\\\"Segoe UI\\\",\\\"PingFang SC\\\",\\\"Microsoft YaHei\\\",sans-serif;color:var(--text-main)}\\nbutton{font:inherit;color:inherit;cursor:pointer;-webkit-tap-highlight-color:transparent;white-space:nowrap}\\nbutton:focus-visible{outline:2px solid #6c91e6;outline-offset:3px}\\nsvg{display:block;flex-shrink:0}\\n.page{width:100%;max-width:375px;min-height:833px;height:833px;margin:0 auto;overflow:hidden;display:flex;flex-direction:column;background:var(--bg-page)}\\n.world{height:143px;min-height:143px;position:relative;overflow:hidden;background:radial-gradient(ellipse at 17% 90%,#e6e4dd 0 8%,transparent 26%),radial-gradient(ellipse at 68% 98%,#eef1ee 0 12%,transparent 33%),radial-gradient(ellipse at 35% 12%,#d3d5cd 0 2%,transparent 19%),linear-gradient(145deg,#6d9dbc,#9bbfda 65%,#c1d3df)}\\n.world:after{content:\\\"\\\";position:absolute;inset