bute(\'aria-pressed\')) return el.getAttribute(\'aria-pressed\') === \'true\';\\n    if (el.hasAttribute(\'data-state\')) return el.getAttribute(\'data-state\') === \'on\';\\n    return el.classList.contains(\'on\') || el.classList.contains(\'checked\') || el.classList.contains(\'active\');\\n  }\\n  function state(el, value) {\\n    el.setAttribute(\'aria-checked\', String(value));\\n    if (native(el)) {\\n      el.checked = value;\\n      if (value) el.setAttribute(\'checked\', \'\'); else el.removeAttribute(\'checked\');\\n    }\\n    if (el.getAttribute(\'data-wf-control\') === \'switch\') {\\n      el.setAttribute(\'aria-pressed\', String(value));\\n      el.setAttribute(\'data-state\', value ? \'on\' : \'off\');\\n    }\\n  }\\n  function normalize() {\\n    document.querySelectorAll(selector).forEach(function (el) {\\n      var type = kind(el);\\n      if (!type) return;\\n      var value = checked(el);\\n      el.setAttribute(\'data-wf-control\', type);\\n      if (!native(el)) {\\n        el.setAttribute(\'role\', type);\\n        if (el.tagName === \'BUTTON\') el.setAttribute(\'type\', \'button\');\\n        else if (!el.hasAttribute(\'tabindex\')) el.setAttribute(\'tabindex\', \'0\');\\n      }\\n      if (!el.hasAttribute(\'data-wf-control-version\')) {\\n        // Initialize geometry once. Subsequent editor moves/resizes must survive save/reload.\\n        el.style.width = type === \'switch\' ? \'44px\' : \'20px\';\\n        el.style.height = type === \'switch\' ? \'25px\' : \'20px\';\\n        el.setAttribute(\'data-wf-control-version\', \'1\');\\n      }\\n      state(el, value);\\n    });\\n  }\\n  function radioGroup(el) { return el.getAttribute(\'data-wf-radio-group\') || el.getAttribute(\'name\') || \'\'; }\\n  function update(el) {\\n    var type = el.getAttribute(\'data-wf-control\');\\n    if (type === \'radio\') {\\n      var group = radioGroup(el);\\n      document.querySelectorAll(\'[data-wf-control=\\\"radio\\\"]\').forEach(function (peer) {\\n        if (peer !== el \\u0026\\u0026 group \\u0026\\u0026 radioGroup(peer) === group \\u0026\\u0026 peer.form === el.form) state(peer, false);\\n      });\\n      state(el, true);\\n    } else state(el, native(el) ? el.checked : !checked(el));\\n  }\\n  document.addEventListener(\'click\', function (event) {\\n    var el = event.target.closest \\u0026\\u0026 event.target.closest(\'[data-wf-control]\');\\n    if (!el) return;\\n    if (editing()) { if (native(el)) event.preventDefault(); return; }\\n    if (!native(el)) event.preventDefault();\\n    // One owner: neither the old .wf-sw handler nor the generic toggle runtime may toggle again.\\n    event.stopImmediatePropagation();\\n    if (disabled(el)) { event.preventDefault(); return; }\\n    update(el);\\n  }, true);\\n  document.addEventListener(\'change\', function (event) {\\n    if (editing() || !native(event.target) || !event.target.hasAttribute(\'data-wf-control\')) return;\\n    update(event.target);\\n  }, true);\\n  document.addEventListener(\'keydown\', function (event) {\\n    var el = event.target.closest \\u0026\\u0026 event.target.closest(\'[data-wf-control]\');\\n    if (!el || editing() || disabled(el) || native(el) || el.tagName === \'BUTTON\') return;\\n    if (event.key === \' \' || event.key === \'Enter\') { event.preventDefault(); el.click(); }\\n  });\\n  window.__wfControls = { normalize: normalize };\\n  function start() {\\n    normalize();\\n    // Controls inserted by the canvas or an opened local panel use the same implementation.\\n    if (typeof MutationObserver !== \'undefined\') new MutationObserver(function (changes) {\\n      var added = changes.some(function (change) {\\n        return Array.from(change.addedNodes).some(function (node) {\\n          return node.nodeType === 1 \\u0026\\u0026 (node.matches(selector) || node.querySelector(selector));\\n        });\\n      });\\n      if (added) normalize();\\n    }).observe(document.body, { childList: true, subtree: true });\\n  }\\n  if (document.readyState === \'loading\') document.addEventListener(\'DOMContentLoaded\', start);\\n  else start();\\n})();\\n\\u003c/script\\u003e\\u003cscript data-wf-prototype-runtime=\\\"true\\\"\\u003e(function () {\\n  // Generated pages contain static markup. This shared runtime changes state only.\\n  function hosted() { return !!document.querySelector(\'script[data-wf-inject]\'); }\\n  function editing() { return hosted() \\u0026\\u0026 !document.body.classList.contains(\'wf-interactive\'); }\\n  function feedback(text) {\\n    var box = document.getElementById(\'wf-prototype-feedback\');\\n    if (!box) return;\\n    box.textContent = text;\\n    box.hidden = false;\\n    clearTimeout(window.__wfFeedbackTimer);\\n    window.__wfFeedbackTimer = setTimeout(function () { box.hidden = true; }, 2200);\\n  }\\n  function close(modal) { if (modal) modal.classList.remove(\'wf-show\'); }\\n  document.addEventListener(\'click\', function (event) {\\n    if (editing()) return;\\n    var target = event.target.closest \\u0026\\u0026 event.target.closest(\'[data-nav],[data-modal],[data-action],[data-wf-tab],[data-wf-toggle],[data-wf-feedback],.wf-modal\');\\n    if (!target) return;\\n    // The canvas owns navigation, back and modal events in preview mode.\\n    var routed = target.matches(\'[data-nav],[data-modal],[data-action]\') || target.classList.contains(\'wf-modal\');\\n    if (hosted() \\u0026\\u0026 routed) return;\\n    event.preventDefault();\\n    event.stopImmediatePropagation();\\n    if (target.hasAttribute(\'data-modal\')) {\\n      var modal = document.getElementById(\'wf-modal-\' + target.getAttribute(\'data-modal\'));\\n      if (modal) modal.classList.add(\'wf-show\');\\n    } else if (target.classList.contains(\'wf-modal\') \\u0026\\u0026 event.target === target) {\\n      close(target);\\n    } else if (/^(back|close)$/.test(target.getAttribute(\'data-action\') || \'\')) {\\n      var owner = target.closest(\'.wf-modal\');\\n      if (owner) close(owner);\\n      else if (parent !== window) parent.postMessage({ type: \'wf-back\' }, \'*\');\\n      else feedback(\'已返回\');\\n    } else if (target.hasAttribute(\'data-nav\')) {\\n      if (parent !== window) parent.postMessage({ type: \'wf-nav\', page: target.getAttribute(\'data-nav\') }, \'*\');\\n      else feedback(\'前往「\' + target.getAttribute(\'data-nav\') + \'」：请在项目预览中查看跨页跳转\');\\n    } else if (target.hasAttribute(\'data-wf-tab\')) {\\n      var group = target.getAttribute(\'data-wf-tab\');\\n      document.querySelectorAll(\'[data-wf-tab]\').forEach(function (item) {\\n        if (item.getAttribute(\'data-wf-tab\') !== group) return;\\n        var active = item === target;\\n        item.classList.toggle(\'active\', active);\\n        item.setAttribute(\'aria-pressed\', String(active));\\n        item.setAttribute(\'aria-selected\', String(active));\\n        var panel = document.getElementById(item.getAttribute(\'aria-controls\') || \'\');\\n        if (panel) panel.hidden = !active;\\n      });\\n    } else if (target.hasAttribute(\'data-wf-toggle\')) {\\n      target.setAttribute(\'aria-pressed\', String(target.getAttribute(\'aria-pressed\') !== \'true\'));\\n    }\\n    if (target.hasAttribute(\'data-wf-feedback\')) {\\n      feedback(target.getAttribute(\'data-wf-feedback\'));\\n      if (target.getAttribute(\'data-wf-close-modal\') === \'true\') close(target.closest(\'.wf-modal\'));\\n    }\\n  }, true);\\n  document.addEventListener(\'input\', function (event) {\\n    if (editing() || !event.target.matches(\'[data-wf-search]\')) return;\\n    var scope = document.getElementById(event.target.getAttribute(\'data-wf-search\'));\\n    if (!scope) return;\\n    var query = event.target.value.trim().toLocaleLowerCase();\\n    scope.querySelectorAll(\'[data-wf-search-text]\').forEach(function (item) {\\n      item.hidden = !(item.getAttribute(\'data-wf-search-text\') || item.textContent).toLocaleLowerCase().includes(query);\\n    });\\n  });\\n  document.addEventListener(\'keydown\', function (event) {\\n    if (event.key === \'Escape\' \\u0026\\u0026 !editing() \\u0026\\u0026 !hosted()) {\\n      document.querySelectorAll(\'.wf-modal.wf-show\').forEach(close);\\n    }\\n  });\\n})();\\n\\u003c/script\\u003e\\u003c/body\\u003e\\n\\u003c/html\\u003e\",\"2598\":\"\\u003c!doctype html\\u003e\\n\\u003chtml lang=\\\"zh-CN\\\"\\u003e\\n\\u003chead\\u003e\\n\\u003cmeta charset=\\\"UTF-8\\\"\\u003e\\n\\u003cmeta name=\\\"viewport\\\" content=\\\"width=device-width, initial-scale=1\\\"\\u003e\\n\\u003ctitle\\u003e奖励兑换提示弹窗\\u003c/title\\u003e\\n\\u003cstyle\\u003e\\n:root{\\n  --bg-page:#ead3ac;\\n  --bg-card:#fafafa;\\n  --primary:#403ff1;\\n  --primary-subtle:#e9e8ff;\\n  --text-main:#262626;\\n  --text-sub:#79746b;\\n  --border-light:#ded6c8;\\n  --wf-chrome-status-height:32px;\\n  --wf-chrome-nav-height:75px;\\n  --wf-chrome-nav-font:11px;\\n}\\n*{box-sizing:border-box}\\nbody{margin:0;background:#303033;font-family:-apple-system,BlinkMacSystemFont,\\\"Segoe UI\\\",\\\"PingFang SC\\\",\\\"Microsoft YaHei\\\",sans-serif;color:var(--text-main)}\\nbutton{font:inherit;color:inherit;cursor:pointer;white-space:nowrap;-webkit-tap-highlight-color:transparent}\\nbutton:focus-visible{outline:2px solid #8581ff;outline-offset:4px}\\nsvg{display:block;flex-shrink:0}\\n.page{position:relative;width:100%;max-width:375px;min-height:833px;height:833px;margin:0 auto;overflow:hidden;background:var(--bg-page)}\\n.collection{height:833px;display:flex;flex-direction:column;background:linear-gradient(120deg,#f4e8d0,#e9c494 77%,#efdab8)}\\n.status{height:32px;min-height:32px;display:flex;align-items:center;justify-content:space-between;padding:0 24px;color:#20212b}\\n.time{font-size:14px;font-weight:600;line-height:18px}\\n.signals{display:flex;align-items:center;gap:5px}\\n.header{height:54px;flex:none;display:flex;align-items:center;padding:0 16px 0 25px;gap:8px}\\n.header h1{margin:0 auto 0 0;font-size:20px;font-weight:600}\\n.bal