ent editor moves/resizes must survive save/reload.\n        el.style.width = type === \'switch\' ? \'44px\' : \'20px\';\n        el.style.height = type === \'switch\' ? \'25px\' : \'20px\';\n        el.setAttribute(\'data-wf-control-version\', \'1\');\n      }\n      state(el, value);\n    });\n  }\n  function radioGroup(el) { return el.getAttribute(\'data-wf-radio-group\') || el.getAttribute(\'name\') || \'\'; }\n  function update(el) {\n    var type = el.getAttribute(\'data-wf-control\');\n    if (type === \'radio\') {\n      var group = radioGroup(el);\n      document.querySelectorAll(\'[data-wf-control=\"radio\"]\').forEach(function (peer) {\n        if (peer !== el && group && radioGroup(peer) === group && peer.form === el.form) state(peer, false);\n      });\n      state(el, true);\n    } else state(el, native(el) ? el.checked : !checked(el));\n  }\n  document.addEventListener(\'click\', function (event) {\n    var el = event.target.closest && event.target.closest(\'[data-wf-control]\');\n    if (!el) return;\n    if (editing()) { if (native(el)) event.preventDefault(); return; }\n    if (!native(el)) event.preventDefault();\n    // One owner: neither the old .wf-sw handler nor the generic toggle runtime may toggle again.\n    event.stopImmediatePropagation();\n    if (disabled(el)) { event.preventDefault(); return; }\n    update(el);\n  }, true);\n  document.addEventListener(\'change\', function (event) {\n    if (editing() || !native(event.target) || !event.target.hasAttribute(\'data-wf-control\')) return;\n    update(event.target);\n  }, true);\n  document.addEventListener(\'keydown\', function (event) {\n    var el = event.target.closest && event.target.closest(\'[data-wf-control]\');\n    if (!el || editing() || disabled(el) || native(el) || el.tagName === \'BUTTON\') return;\n    if (event.key === \' \' || event.key === \'Enter\') { event.preventDefault(); el.click(); }\n  });\n  window.__wfControls = { normalize: normalize };\n  function start() {\n    normalize();\n    // Controls inserted by the canvas or an opened local panel use the same implementation.\n    if (typeof MutationObserver !== \'undefined\') new MutationObserver(function (changes) {\n      var added = changes.some(function (change) {\n        return Array.from(change.addedNodes).some(function (node) {\n          return node.nodeType === 1 && (node.matches(selector) || node.querySelector(selector));\n        });\n      });\n      if (added) normalize();\n    }).observe(document.body, { childList: true, subtree: true });\n  }\n  if (document.readyState === \'loading\') document.addEventListener(\'DOMContentLoaded\', start);\n  else start();\n})();\n</script>\n\n\n<title>扭蛋页</title>\n<style>\n:root{\n  --bg-page:#8c8794;--bg-card:#f0b3d0;--primary:#ec9fc3;--primary-subtle:#ffe2ef;\n  --text-main:#694357;--text-sub:#95647c;--border-light:#ffdfed;\n  --wf-chrome-nav-bg:#fff;--wf-chrome-nav-ink:#686969;--wf-chrome-active:#fff;\n  --wf-chrome-active-bg:linear-gradient(#879bfa,#88d4ff);--wf-chrome-border:#dedee5;\n}\n*{box-sizing:border-box}\nbody{margin:0;background:#303033;font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",\"PingFang SC\",\"Microsoft YaHei\",sans-serif;color:var(--text-main)}\nbutton{font:inherit;color:inherit;cursor:pointer;-webkit-tap-highlight-color:transparent}\nbutton:active{filter:brightness(.95)}\nbutton:focus-visible{outline:2px solid #fff4b4;outline-offset:3px}\nsvg{display:block;flex-shrink:0}\nbutton{white-space:nowrap}\n.page{width:100%;max-width:375px;height:833px;min-height:833px;margin:0 auto;position:relative;overflow:hidden;display:flex;flex-direction:column;background:radial-gradient(ellipse at 49% 72%,#c5b0c1 0,transparent 57%),linear-gradient(155deg,#73737e,#85808b 50%,#b3a2b5)}\n.status{height:32px;flex:none;padding:0 24px;display:flex;align-items:center;justify-content:space-between;color:#fff;font-size:14px;font-weight:600;line-height:18px}\n.signals{display:flex;align-items:center;gap:5px}\n.battery{height:13px;border:1px solid #f5f4fa;border-radius:3px;position:relative;padding:0 3px;font-size:10px;font-weight:500;line-height:11px}\n.battery::after{content:\"\";position:absolute;width:2px;height:6px;right:-3px;top:2px;background:#f5f4fa;border-radius:1px}\n.header{height:46px;flex:none;padding:8px 24px 0;display:flex;align-items:center;justify-content:space-between;gap:10px}\n.balance{display:flex;align-items:center;gap:5px;height:27px;padding:0 7px;border:1px solid #64616d55;border-radius:18px;background:#68667220;color:#15151a;white-space:nowrap}\n.balance span{font-size:14px}\n.tabs{height:33px;display:flex;align-items:center;flex:none;border-radius:20px;background:#4a4a52aa;padding:1px}\n.tabs button{border:0;background:transparent;color:#d2ced4;font-size:16px;font-weight:500;border-radius:20px;height:31px;padding:0 16px}\n.tabs button.active{color:#fff;background:#3939408c;box-shadow:inset 0 1px 2px #ffffff0b}\n.header-actions{display:flex;align-items:center;gap:15px}\n.header-icon{border:0;background:none;width:22px;height:29px;padding:0;display:flex;align-items:center;justify-content:center;color:#101014}\n.stage{position:relative;flex:1;min-height:0;display:flex;align-items:center;flex-direction:column;padding-top:1px;isolation:isolate}\n.banner{position:relative;z-index:3;width:295px;height:77px;flex:none;padding:11px 7px 6px 67px;border:3px solid #ffe0ef;border-radius:18px 18px 14px 14px;background:linear-gradient(#e996bf,#d66ca0 48%,#edaaca);box-shadow:inset 0 0 0 2px #f9c9e0,0 3px 3px #79516966;display:flex;flex-direction:column;justify-content:center;align-items:center}\n.banner-title{position:relative;z-index:2;font-size:21px;line-height:29px;font-weight:900;white-space:nowrap;letter-spacing:-1px;color:white;text-shadow:-2px -2px #a93840,2px -2px #a93840,-2px 2px #a93840,2px 2px #a93840,0 3px #a93840}\n.banner-subtitle{position:relative;z-index:3;color:#ad2624;font-size:15px;line-height:21px;letter-spacing:-.7px;font-weight:900;white-space:nowrap;text-shadow:-1px -1px #ffd040,1px -1px #ffd040,-1px 1px #ffd040,1px 1px #ffd040,0 2px #ffb222}\n.banner-portrait{position:absolute;left:6px;bottom:4px;width:68px;height:76px;border-radius:39px 39px 9px 9px;background:linear-gradient(#bd7196,#ffdfdd);border:3px solid #ffe3f0;overflow:hidden}\n.banner-portrait svg{width:100%;height:100%}\n.server-count{position:absolute;z-index:5;left:2px;bottom:8px;font-size:10px;line-height:16px;color:#ffef80;background:#222024da;padding:0 8px;border:1px solid #dbb6b8;border-radius:12px;white-space:nowrap}\n.side-links{position:absolute;right:0;top:-3px;display:flex;flex-direction:column;gap:4px;z-index:6}\n.side-link{writing-mode:vertical-rl;letter-spacing:2px;height:61px;width:20px;padding:5px 2px;border:1px solid #d7d0dc55;border-right:0;border-radius:10px 0 0 10px;background:#d7cedb3d;color:#fff;font-size:11px;line-height:14px}\n.machine{position:relative;width:327px;height:548px;flex:none;margin-top:-8px;border-radius:49px 49px 35px 35px;background:linear-gradient(100deg,#efb2d0 0%,#e7a0c1 51%,#e3a2c0 100%);box-shadow:inset 4px 2px 6px #ffe6f1, inset -5px -7px 9px #a6658a66,0 17px 16px -13px #493845a8}\n.machine::before,.machine::after{content:\"\";position:absolute;bottom:-13px;width:32px;height:17px;background:linear-gradient(90deg,#c27c9e,#d997b8 55%,#bb7397);box-shadow:inset 0 -3px 3px #ab6b8e70,0 4px 6px #4e344936;border-radius:0 0 7px 7px;z-index:-1}\n.machine::before{left:55px}.machine::after{right:55px}\n.machine-header{height:62px;display:flex;align-items:center;gap:10px;padding:14px 16px 7px}\n.announcement{flex:1;min-width:0;height:35px;border:2px solid #d99bb9;border-radius:22px;background:#facbdf;box-shadow:inset 1px 2px 4px #bf72966b,0 1px 1px #fff6;display:flex;align-items:center;gap:5px;padding:5px 7px}\n.announcement-avatar{width:21px;height:21px;flex:none;border-radius:50%;overflow:hidden;background:linear-gradient(140deg,#a7bb75,#3c4f3d);border:1px solid #f9e4d7}\n.announcement-avatar svg{width:100%;height:100%}\n.announcement-text{font-size:10px;line-height:15px;color:#9b5f7b;white-space:nowrap;overflow:hidden;text-overflow:clip}\n.machine-tool{width:31px;height:35px;flex:none;border:0;border-radius:50%;background:radial-gradient(circle at 45% 45%,#ffdaea,#edb4cf 58%,#c583a5);box-shadow:0 1px 2px #ce8aab;display:flex;align-items:center;flex-direction:column;justify-content:center;padding:1px 0 0;gap:0;color:#985e7d}\n.machine-tool span{font-size:10px;line-height:12px;padding:0 3px;border-radius:6px;background:#ffe1edaa;box-shadow:0 1px 2px #c381a455}\n.machine-body{height:446px;margin:0 15px;display:grid;grid-template-columns:minmax(0,1fr) 82px;gap:10px}\n.prize-side{min-width:0;padding-top:8px;display:flex;flex-direction:column}\n.prize-window{height:364px;flex:none;padding:15px 7px 16px;border:9px solid #f9c5df;border-radius:32px;background:linear-gradient(120deg,#bbc4d0,#b0b5c1 42%,#c6cbd0);box-shadow:0 0 0 3px #df95b9,inset 0 0 0 3px #f9f5f3,inset 0 1px 12px 5px #8c8b9c88,0 2px 3px #ffcfe780;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));grid-template-rows:repeat(4,69px);column-gap:6px;row-gap:12px}\n.prize-card{position:relative;min-width:0;height:69px;display:flex;flex-direction:column;align-items:center;overflow:hidden;border:3px solid #f2f7f5;border-radius:11px;background:linear-gradient(120deg,#47baff,#158fcd);box-shadow:2px 3px 2px #6367786b,inset 2px 0 4px #d5f4ff}\n.prize-card::before{content:\"\";position:absolute;z-index:3;left:35%;top:-1px;width:30%;height:3px;border-radius:0 0 4px 4px;background:#fff}\n.prize-card.purple{background:linear-gradient(120deg,#b149dc,#db8cfa)}\n.prize-card.gold{background:linear-gradient(120deg,#ffad36,#ffdf63)}\n.portrait{position:relative;width:100%;height:49px;flex:none;aspect-ratio:1/1;overflow:hidden;background:linear-gradient(105deg,#fff3,transparent 55%);display:flex;align-items:center;justify-content:center}\n.portrait svg{width:100%;height:100%;filter:drop-shadow(1px 1px 1px #253e5c45)}\n.prize-name{position:relative;z-index:2;max-width:100%;width:100%;margin-top:-1px;height:14px;flex:none;text-align:center;background:linear-gradient(#89e2ff,#4fc9f5);color:#143b53;font-size:8px;font-weight:500;line-height:14px;white-space:nowrap;letter-spacing:-.4px;border-radius:2px}\n.gold .prize-name{background:linear-gradient(#ffe77f,#ffd141);color:#63491c}\n.outlet{height:57px;flex:none;margin-top:21px;border:1.5px solid #cd7da4;border-radius:17px;background:linear-gradient(140deg,#a45a83,#bb719b 55%,#c986ad);box-shadow:inset 1px 3px 4px #8c466b44,inset 0 -8px 0 #a7567b55,0 1px #ffd1e9;position:relative;overflow:hidden}\n.outlet::after{content:\"\";position:absolute;inset:0;background:linear-gradient(45deg,transparent 60%,#ffcee920 60% 68%,transparent 68% 75%,#ffcee918 75% 80%,transparent 80%)}\n.controls{display:flex;flex-direction:column;align-items:stretch}\n.draw-type{height:34px;flex:none;padding:0;border:2px solid #ffffb0;border-radius:21px;background:linear-gradient(#fff3a2,#ffd157 68%,#ffbf5c);box-shadow:0 0 5px #fff89b,inset 0 0 0 1px #fff7d7;color:#8f5b16;font-size:13px;line-height:30px;font-weight:800}\n.draw-type.secondary{height:32px;margin-top:6px;background:linear-gradient(#fbd4e7,#efb3d1);border:1px solid #ffd2e6;box-shadow:0 2px 2px #d88fb155;color:#97617d;font-weight:700;line-height:30px}\n.promo-art{height:108px;flex:none;aspect-ratio:77/108;margin-top:6px;border-radius:18px;background:radial-gradient(ellipse at 50% 20%,#fff8d6,#ffd870 68%,#ffbd62);position:relative;overflow:hidden}\n.promo-art svg{height:108px;width:100%}\n.promo-caption{position:absolute;bottom:7px;left:0;right:0;text-align:center;transform:rotate(-7deg);color:#fff9df;font-size:12px;font-weight:900;line-height:13px;text-shadow:-1px -1px #a76834,1px -1px #a76834,-1px 1px #a76834,1px 1px #a76834,0 2px #a76834}\n.pity{height:40px;flex:none;margin:6px -3px 0;display:flex;align-items:center;justify-content:center;flex-direction:column;font-size:17px;line-height:19px;font-weight:900;letter-spacing:-.